import itertools
import random
import subprocess

UINT_MAX = 2**32 - 1

def expected(in_base, digits, out_base):
    if in_base < 2 or out_base < 2 or any(d >= in_base for d in digits):
        return ["INVALID"]
    value = 0
    for d in digits:
        value = value * in_base + d
    if value == 0:
        return ["OK"]
    out = []
    while value:
        out.append(value % out_base)
        value //= out_base
    return ["OK"] + [str(x) for x in reversed(out)]

cases = []
# Exhaustive small cases, including invalid digits and empty vectors.
for in_base in range(0, 7):
    for length in range(0, 4):
        for digits in itertools.product(range(0, 7), repeat=length):
            for out_base in range(0, 7):
                cases.append((in_base, list(digits), out_base))
# Targeted canonical and boundary cases.
cases.extend([
    (2, [1, 0, 1, 0, 1, 0], 10),
    (10, [4, 2], 2),
    (3, [1, 1, 2, 0], 16),
    (16, [2, 10], 3),
    (97, [3, 46, 60], 73),
    (7, [0, 6, 0], 10),
    (10, [0, 0, 0], 2),
    (10, [], 2),
    (2, [UINT_MAX - 1], UINT_MAX),
    (UINT_MAX, [UINT_MAX - 1, 1], 2),
    (UINT_MAX, [UINT_MAX - 1, 1], UINT_MAX),
    (UINT_MAX, [UINT_MAX], 10),
    (10, [UINT_MAX], 2),
])
# Random large cases.
rng = random.Random(20261104)
special_bases = [2, 3, 7, 10, 16, 255, 256, 65535, 65536, 10**9, UINT_MAX - 1, UINT_MAX]
for _ in range(2000):
    in_base = rng.choice(special_bases) if rng.random() < 0.5 else rng.randint(2, UINT_MAX)
    out_base = rng.choice(special_bases) if rng.random() < 0.5 else rng.randint(2, UINT_MAX)
    length = rng.randint(0, 12)
    digits = [rng.randrange(in_base) for _ in range(length)]
    cases.append((in_base, digits, out_base))

stdin_lines = []
for in_base, digits, out_base in cases:
    stdin_lines.append(f"{in_base} {len(digits)} {out_base} " + " ".join(map(str, digits)))
proc = subprocess.run(["/tmp/ayb_driver"], input="\n".join(stdin_lines) + "\n", text=True, capture_output=True, check=True)
actual_lines = proc.stdout.splitlines()
assert len(actual_lines) == len(cases), (len(actual_lines), len(cases))
failures = []
for i, ((in_base, digits, out_base), actual) in enumerate(zip(cases, actual_lines)):
    want = " ".join(expected(in_base, digits, out_base))
    if actual != want:
        failures.append((i, in_base, digits, out_base, want, actual))
        if len(failures) >= 10:
            break
if failures:
    for failure in failures:
        print("FAIL", failure)
    raise SystemExit(1)
print(f"All {len(cases)} independent reference cases passed")
